CREATE TABLE ai_requests(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,user_id TEXT NOT NULL,idem_key TEXT NOT NULL,request_hash TEXT NOT NULL,path TEXT NOT NULL,batch_parent_id TEXT,status TEXT NOT NULL CHECK(status IN('pending','done','failed')),hold_id TEXT NOT NULL,deadline_at INTEGER NOT NULL,response TEXT,cache_expires_at INTEGER,receipt_json TEXT,created_at INTEGER NOT NULL,finished_at INTEGER,retain_until INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,user_id,idem_key));
